# Verify the semi-synthetic ΔTPR=+0.508 at p=0.5 for the main analysis
# This is from sec:groundtruth: "Semi-synthetic injection confirms detection power (ΔTPR = +0.508)"
# This is for MMLU (cross-subject) temporal matching

# Check the dose_response_summary for temporal/standard at p=0.5
import csv
data = []
with open('/home/ubuntu/.agent-ml-research-idea_gen_0520_2/projects/irt_equated_bench_regen/artifacts/plan_011_semi_synthetic_validation/data/dose_response_summary.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        data.append(row)

# Temporal + external (cross-subject) at p=0.5
for r in data:
    if r['cohort_type'] == 'temporal' and r['mh_variant'] == 'external' and abs(float(r['p']) - 0.5) < 0.01:
        # delta TPR from p=0 baseline
        for r2 in data:
            if r2['cohort_type'] == 'temporal' and r2['mh_variant'] == 'external' and abs(float(r2['p'])) < 0.01:
                base_tpr = float(r2['tpr_mean'])
        delta_tpr = float(r['tpr_mean']) - base_tpr
        print(f"Temporal/external p=0.5: TPR={r['tpr_mean']}, ΔTPR={delta_tpr:.3f}, FPR={r['fpr_mean']}")

# Also temporal + anchor at p=0.5
for r in data:
    if r['cohort_type'] == 'temporal' and r['mh_variant'] == 'anchor' and abs(float(r['p']) - 0.5) < 0.01:
        for r2 in data:
            if r2['cohort_type'] == 'temporal' and r2['mh_variant'] == 'anchor' and abs(float(r2['p'])) < 0.01:
                base_tpr = float(r2['tpr_mean'])
        delta_tpr = float(r['tpr_mean']) - base_tpr
        print(f"Temporal/anchor p=0.5: TPR={r['tpr_mean']}, ΔTPR={delta_tpr:.3f}, FPR={r['fpr_mean']}")

# temporal + standard
for r in data:
    if r['cohort_type'] == 'temporal' and r['mh_variant'] == 'standard' and abs(float(r['p']) - 0.5) < 0.01:
        for r2 in data:
            if r2['cohort_type'] == 'temporal' and r2['mh_variant'] == 'standard' and abs(float(r2['p'])) < 0.01:
                base_tpr = float(r2['tpr_mean'])
        delta_tpr = float(r['tpr_mean']) - base_tpr
        print(f"Temporal/standard p=0.5: TPR={r['tpr_mean']}, ΔTPR={delta_tpr:.3f}, FPR={r['fpr_mean']}")
EOF
